# POST /api/sheets/{sheetId}/claims/{claimId}/status — move a claim to a new status (body
# {status, user}): DRAFT to OPEN, OPEN to SETTLED, DRAFT or OPEN to VOID. Refused (400) for any
# other change, when the user who opened the claim tries to settle it, when the claim is not on
# the sheet, when its date falls in a closed period, or when a clerk (any user
# not assigned steward) settles a claim whose due is above the sheet's clerk limit; nothing is stored then. Opening records the user as the claim's opened-by. A stored change is
# recorded in the audit file as CLAIM_OPENED, CLAIM_SETTLED or CLAIM_VOIDED.
validate:
  class: net.officefloor.hq.app.claim.ValidateStatus
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
